// And groups predicates with the AND operator between them.
func And(predicates ...predicate.NodeCommand) predicate.NodeCommand {
	return predicate.NodeCommand(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.NodeCommand) predicate.NodeCommand {
	return predicate.NodeCommand(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.NodeCommand) predicate.NodeCommand {
	return predicate.NodeCommand(sql.NotPredicates(p))
}
